PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE _migrations_smoketest (
  id INTEGER PRIMARY KEY,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  display_name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'gm', 
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, username TEXT, login_code_hash TEXT, auth_id TEXT, password_hash TEXT, password_salt TEXT, password_iterations INTEGER, password_set_at INTEGER);
CREATE TABLE invite_codes (
  code TEXT PRIMARY KEY,
  role TEXT NOT NULL DEFAULT 'gm', 
  used_by_user_id TEXT,            
  used_at INTEGER,
  expires_at INTEGER,              
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (used_by_user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  expires_at INTEGER NOT NULL,      
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE events (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  type TEXT NOT NULL,               
  start_at INTEGER,                 
  lock_at INTEGER NOT NULL,         
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, manual_lock INTEGER NOT NULL DEFAULT 0, manual_unlock INTEGER NOT NULL DEFAULT 0, results_published_at INTEGER);
CREATE TABLE entries (
  id TEXT PRIMARY KEY,
  event_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  submitted_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  FOREIGN KEY (event_id) REFERENCES events(id),
  FOREIGN KEY (user_id) REFERENCES users(id),
  UNIQUE (event_id, user_id)
);
CREATE TABLE options_cache (
  event_id TEXT NOT NULL,
  provider TEXT NOT NULL,              
  cache_key TEXT NOT NULL,             
  payload_json TEXT NOT NULL,          
  fetched_at INTEGER NOT NULL,         
  PRIMARY KEY (event_id, provider, cache_key)
);
CREATE TABLE entry_scores (
  event_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  score_total INTEGER NOT NULL DEFAULT 0,
  breakdown_json TEXT,
  computed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL
  DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (event_id, user_id),
  FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE event_results (
  event_id TEXT PRIMARY KEY,
  payload_json TEXT NOT NULL,
  published_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE TABLE results (
  event_id TEXT PRIMARY KEY,
  payload_json TEXT,
  published_at TEXT,
  updated_at INTEGER
);
CREATE TABLE managers (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  team_name TEXT NOT NULL,
  location TEXT,
  bio TEXT,
  photo TEXT,
  favorite_team TEXT,
  persona TEXT,
  philosophy TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, sleeper_user_id TEXT, sleeper_roster_id INTEGER, sleeper_avatar TEXT, sleeper_username TEXT, metadata_json TEXT);
CREATE TABLE standings_snapshots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season TEXT NOT NULL,
  manager_id TEXT NOT NULL,
  wins INTEGER NOT NULL DEFAULT 0,
  losses INTEGER NOT NULL DEFAULT 0,
  ties INTEGER NOT NULL DEFAULT 0,
  points_for REAL NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()), points_against REAL NOT NULL DEFAULT 0, streak_type TEXT, streak_value INTEGER NOT NULL DEFAULT 0, rank INTEGER,
  FOREIGN KEY (manager_id) REFERENCES managers(id) ON DELETE CASCADE
);
CREATE TABLE posts (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  excerpt TEXT,
  body TEXT,
  tag TEXT,
  published_at TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, subtitle TEXT, post_type TEXT NOT NULL
DEFAULT 'feature', status TEXT NOT NULL
DEFAULT 'draft', author_name TEXT, author_user_id TEXT, source_type TEXT NOT NULL
DEFAULT 'manual', recap_season INTEGER, recap_week INTEGER, featured INTEGER NOT NULL
DEFAULT 0, updated_at INTEGER);
CREATE TABLE roster_players (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season TEXT NOT NULL,
  manager_id TEXT NOT NULL,
  sleeper_roster_id INTEGER,
  player_id TEXT NOT NULL,
  slot TEXT,
  lineup_order INTEGER,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE drafts (
  id TEXT PRIMARY KEY,
  season TEXT NOT NULL,
  label TEXT NOT NULL,
  kind TEXT NOT NULL,
  status TEXT,
  draft_order_json TEXT,
  settings_json TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE draft_picks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  draft_id TEXT NOT NULL,
  season TEXT NOT NULL,
  pick_no INTEGER,
  round INTEGER,
  manager_id TEXT,
  player_id TEXT,
  amount REAL,
  is_keeper INTEGER NOT NULL DEFAULT 0,
  metadata_json TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE matchups (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season TEXT NOT NULL,
  week INTEGER NOT NULL,
  matchup_id INTEGER,
  roster_id INTEGER,
  manager_id TEXT,
  starters_json TEXT,
  players_json TEXT,
  points REAL NOT NULL DEFAULT 0,
  custom_points REAL,
  metadata_json TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE transactions (
  id TEXT PRIMARY KEY,
  season TEXT NOT NULL,
  week INTEGER,
  kind TEXT,
  status TEXT,
  creator_id TEXT,
  roster_ids_json TEXT,
  adds_json TEXT,
  drops_json TEXT,
  draft_picks_json TEXT,
  waiver_budget_json TEXT,
  metadata_json TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE badge_definitions (
  key TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  icon TEXT,
  tone TEXT,
  description TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, category TEXT NOT NULL DEFAULT 'other', sort_order INTEGER NOT NULL DEFAULT 0, scope TEXT NOT NULL DEFAULT 'season', award_mode TEXT NOT NULL DEFAULT 'manual', automation_key TEXT, repeatable INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, updated_at INTEGER);
CREATE TABLE manager_badges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season TEXT NOT NULL,
  badge_key TEXT NOT NULL,
  manager_id TEXT NOT NULL,
  reason TEXT,
  score REAL,
  metadata_json TEXT,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
, week INTEGER, opponent_manager_id TEXT, opponent_score REAL, nominated_by_manager_id TEXT, source TEXT NOT NULL DEFAULT 'manual', dedupe_key TEXT, revoked_at INTEGER, awarded_by TEXT, updated_at INTEGER);
CREATE TABLE draft_budget_ledger (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  season TEXT NOT NULL,
  manager_id TEXT NOT NULL,
  starting_budget REAL NOT NULL DEFAULT 200,
  spent_budget REAL NOT NULL DEFAULT 0,
  remaining_budget REAL NOT NULL DEFAULT 200,
  keeper_commitment INTEGER NOT NULL DEFAULT 0,
  max_purchase REAL NOT NULL DEFAULT 0,
  average_purchase REAL NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE manager_financial_snapshots (
  id TEXT PRIMARY KEY,
  manager_id TEXT NOT NULL,
  season INTEGER NOT NULL,
  budget INTEGER NOT NULL DEFAULT 0,
  spent INTEGER NOT NULL DEFAULT 0,
  remaining INTEGER NOT NULL DEFAULT 0,
  dead_money INTEGER NOT NULL DEFAULT 0,
  notes TEXT,
  created_at INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE sleeper_users (
  sleeper_user_id TEXT PRIMARY KEY,
  display_name TEXT,
  avatar TEXT,
  updated_at INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE sleeper_rosters (
  roster_id INTEGER PRIMARY KEY,
  owner_id TEXT,
  starters_json TEXT,
  players_json TEXT,
  settings_json TEXT,
  metadata_json TEXT,
  updated_at INTEGER NOT NULL DEFAULT 0
, season INTEGER, league_id TEXT);
CREATE TABLE sleeper_transactions (
  transaction_id TEXT PRIMARY KEY,
  type TEXT,
  status TEXT,
  roster_ids_json TEXT,
  adds_json TEXT,
  drops_json TEXT,
  draft_picks_json TEXT,
  waiver_budget_json TEXT,
  created_at INTEGER,
  updated_at INTEGER NOT NULL DEFAULT 0
, season INTEGER, league_id TEXT, round INTEGER);
CREATE TABLE rivals (
  manager_id TEXT NOT NULL,
  rival_manager_id TEXT NOT NULL,
  wins INTEGER NOT NULL DEFAULT 0,
  losses INTEGER NOT NULL DEFAULT 0,
  ties INTEGER NOT NULL DEFAULT 0,
  notes TEXT,
  PRIMARY KEY (manager_id, rival_manager_id)
);
CREATE TABLE badges (
  id TEXT PRIMARY KEY,
  slug TEXT UNIQUE,
  name TEXT NOT NULL,
  tier TEXT,
  description TEXT
);
CREATE TABLE league_sync_runs (
  id TEXT PRIMARY KEY,
  source TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'ok',
  season INTEGER,
  week INTEGER,
  summary_json TEXT,
  error_text TEXT,
  created_at INTEGER NOT NULL DEFAULT 0
, league_id TEXT, mode TEXT DEFAULT 'sync');
CREATE TABLE sleeper_rosters_seasonal (
  id TEXT PRIMARY KEY,
  league_id TEXT NOT NULL,
  season INTEGER NOT NULL,
  roster_id INTEGER NOT NULL,
  owner_id TEXT,
  starters_json TEXT,
  players_json TEXT,
  settings_json TEXT,
  metadata_json TEXT,
  updated_at INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE sleeper_transactions_seasonal (
  id TEXT PRIMARY KEY,
  league_id TEXT NOT NULL,
  season INTEGER NOT NULL,
  round INTEGER,
  transaction_id TEXT NOT NULL,
  type TEXT,
  status TEXT,
  roster_ids_json TEXT,
  adds_json TEXT,
  drops_json TEXT,
  draft_picks_json TEXT,
  waiver_budget_json TEXT,
  created_at INTEGER,
  updated_at INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE nfl_bye_weeks (
  season INTEGER NOT NULL,
  week INTEGER NOT NULL,
  team TEXT NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  PRIMARY KEY (season, team)
);
CREATE TABLE draft_capital_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  
  futures_year INTEGER NOT NULL,

  
  manager_id TEXT NOT NULL,

  
  
  
  amount_cents INTEGER NOT NULL,

  
  
  
  
  
  
  
  
  entry_type TEXT NOT NULL,

  
  transaction_date TEXT,

  
  league_season INTEGER,
  league_week INTEGER,

  
  sleeper_transaction_id TEXT,

  
  transfer_id TEXT,

  
  counterparty_manager_id TEXT,

  note TEXT,

  metadata_json TEXT,

  
  
  
  source TEXT NOT NULL DEFAULT 'manual',

  created_by TEXT,

  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),

  
  voided_at INTEGER,
  voided_by TEXT,

  
  dedupe_key TEXT
);
CREATE TABLE draft_capital_trade_reviews (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  season INTEGER NOT NULL,
  week INTEGER,

  sleeper_transaction_id TEXT NOT NULL,

  
  review_status TEXT NOT NULL DEFAULT 'pending',

  transfer_id TEXT,

  note TEXT,

  reviewed_by TEXT,
  reviewed_at INTEGER,

  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),

  UNIQUE (
    season,
    sleeper_transaction_id
  )
);
CREATE TABLE weekly_recaps (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  season INTEGER NOT NULL,

  week INTEGER NOT NULL
    CHECK (
      week >= 1
      AND week <= 18
    ),

  league_id TEXT NOT NULL,

  
  
  

  draft_title TEXT,
  draft_subtitle TEXT,

  draft_recap_json TEXT,
  draft_packet_json TEXT,
  draft_ai_meta_json TEXT,

  draft_generated_at INTEGER,
  draft_generated_by TEXT,

  
  
  

  published_title TEXT,
  published_subtitle TEXT,

  published_recap_json TEXT,
  published_packet_json TEXT,
  published_ai_meta_json TEXT,

  published_at INTEGER,
  published_by TEXT,

  

  created_at INTEGER NOT NULL
    DEFAULT (unixepoch()),

  updated_at INTEGER NOT NULL
    DEFAULT (unixepoch()),

  UNIQUE (
    season,
    week
  )
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_invite_codes_used_by ON invite_codes(used_by_user_id);
CREATE INDEX idx_sessions_user_id ON sessions(user_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
CREATE INDEX idx_events_lock_at ON events(lock_at);
CREATE UNIQUE INDEX idx_users_username_unique ON users(username);
CREATE INDEX idx_entries_event_id ON entries(event_id);
CREATE INDEX idx_entries_user_id ON entries(user_id);
CREATE INDEX idx_options_cache_event ON options_cache(event_id);
CREATE UNIQUE INDEX idx_entries_event_user_unique
ON entries(event_id, user_id);
CREATE INDEX idx_users_auth_id ON users(auth_id);
CREATE INDEX idx_events_results_published_at ON events(results_published_at);
CREATE INDEX idx_roster_players_season_manager ON roster_players (season, manager_id);
CREATE INDEX idx_draft_picks_season_manager ON draft_picks (season, manager_id);
CREATE INDEX idx_matchups_season_week ON matchups (season, week);
CREATE INDEX idx_transactions_season_week ON transactions (season, week);
CREATE INDEX idx_manager_badges_season_manager ON manager_badges (season, manager_id);
CREATE INDEX idx_draft_budget_ledger_season_manager ON draft_budget_ledger (season, manager_id);
CREATE INDEX idx_manager_financial_snapshots_manager_season
  ON manager_financial_snapshots(manager_id, season);
CREATE INDEX idx_league_sync_runs_source_created
  ON league_sync_runs(source, created_at);
CREATE INDEX idx_sleeper_rosters_season
  ON sleeper_rosters(season, owner_id);
CREATE INDEX idx_sleeper_transactions_season
  ON sleeper_transactions(season, round);
CREATE INDEX idx_league_sync_runs_season
  ON league_sync_runs(season, mode);
CREATE UNIQUE INDEX idx_sleeper_rosters_seasonal_unique
  ON sleeper_rosters_seasonal(league_id, season, roster_id);
CREATE INDEX idx_sleeper_rosters_seasonal_owner
  ON sleeper_rosters_seasonal(season, owner_id);
CREATE UNIQUE INDEX idx_sleeper_transactions_seasonal_unique
  ON sleeper_transactions_seasonal(league_id, season, transaction_id);
CREATE INDEX idx_sleeper_transactions_seasonal_round
  ON sleeper_transactions_seasonal(season, round, created_at);
CREATE INDEX idx_badge_definitions_active_category
ON badge_definitions (
  active,
  category,
  sort_order
);
CREATE INDEX idx_manager_badges_badge_season_week
ON manager_badges (
  badge_key,
  season,
  week
);
CREATE INDEX idx_manager_badges_manager_badge
ON manager_badges (
  manager_id,
  badge_key
);
CREATE INDEX idx_manager_badges_active
ON manager_badges (
  manager_id,
  season
)
WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX idx_manager_badges_dedupe
ON manager_badges (dedupe_key)
WHERE dedupe_key IS NOT NULL
  AND revoked_at IS NULL;
CREATE INDEX idx_nfl_bye_weeks_season_week
ON nfl_bye_weeks (season, week);
CREATE INDEX idx_draft_capital_year_manager
ON draft_capital_entries (
  futures_year,
  manager_id
);
CREATE INDEX idx_draft_capital_transfer
ON draft_capital_entries (
  transfer_id
);
CREATE INDEX idx_draft_capital_sleeper_txn
ON draft_capital_entries (
  sleeper_transaction_id
);
CREATE INDEX idx_draft_capital_created
ON draft_capital_entries (
  created_at DESC
);
CREATE UNIQUE INDEX idx_draft_capital_dedupe
ON draft_capital_entries (
  dedupe_key
)
WHERE
  dedupe_key IS NOT NULL
  AND voided_at IS NULL;
CREATE INDEX idx_draft_trade_reviews_status
ON draft_capital_trade_reviews (
  season,
  review_status
);
CREATE INDEX idx_weekly_recaps_published
ON weekly_recaps (
  published_at DESC
)
WHERE published_recap_json IS NOT NULL;
CREATE INDEX idx_weekly_recaps_season_week
ON weekly_recaps (
  season DESC,
  week DESC
);
CREATE UNIQUE INDEX idx_posts_weekly_recap_source
ON posts (
  recap_season,
  recap_week
)
WHERE source_type = 'weekly_recap';
CREATE INDEX idx_posts_irving_weekly_status
ON posts (
  status,
  published_at DESC
);
CREATE INDEX idx_posts_irving_weekly_updated
ON posts (
  updated_at DESC
);
